Account.ready.then(async user=>{
 if(user.role!=='admin'){location.replace('/sets.html');return;}
 const $=id=>document.getElementById(id),make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
 let users=[],page=1,pending=null,busy=false;const size=10,roles={admin:'Admin',editor:'Editor',learner:'Learner'};
 function ask(u,role){pending={u,role};$('confirm-title').textContent=role?'Change account role?':(u.disabled?'Enable account?':'Disable account?');$('confirm-description').textContent=role?u.name+' ('+u.username+') will become '+roles[role]+'. '+(role==='editor'?'Editors can view drafts and propose content changes for admin approval.':'Editor access will be removed; study data will be retained.'):(u.disabled?'Allow '+u.username+' to sign in again.':'Sign out '+u.username+' and block further sign-in. Study records will be retained.');$('confirm-error').textContent='';$('account-confirm').showModal();}
 function render(){const term=$('user-search').value.trim().toLowerCase();const filtered=users.filter(u=>(u.name+' '+u.username).toLowerCase().includes(term)&&(!$('role-filter').value||u.role===$('role-filter').value)&&(!$('status-filter').value||Boolean(u.disabled)===($('status-filter').value==='disabled')));const pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,pages);$('counts').replaceChildren(make('span',users.length+' users','pill'),make('span',users.filter(u=>!u.disabled).length+' active','pill active'),make('span',users.filter(u=>u.disabled).length+' disabled','pill disabled'));const body=$('user-list');body.replaceChildren();for(const u of filtered.slice((page-1)*size,page*size)){const tr=make('tr');function cell(node){const td=make('td');td.append(node);tr.append(td)}const name=make('div',undefined,'user-name');const avatar=make('span',Array.from(u.username||'?')[0].toUpperCase(),'initial');avatar.setAttribute('aria-hidden','true');name.append(avatar,make('span',u.name));cell(name);cell(make('span',u.username,'username'));
 if(['learner','editor'].includes(u.role)){const select=make('select',undefined,'role-select');select.setAttribute('aria-label','Role for '+u.username);for(const r of ['learner','editor'])select.add(new Option(roles[r],r));select.value=u.role;select.onchange=()=>{const target=select.value;select.value=u.role;if(target!==u.role)ask(u,target)};cell(select)}else cell(make('span','Admin · Locked','pill'));
 cell(make('span',(u.disabled?'● Disabled':'● Active'),'pill '+(u.disabled?'disabled':'active')));if(['learner','editor'].includes(u.role)){const b=make('button',u.disabled?'Enable':'Disable','secondary account-action');b.setAttribute('aria-label',(u.disabled?'Enable ':'Disable ')+u.username);b.onclick=()=>ask(u,null);const actions=make('div');actions.append(b);if(!u.disabled){const reset=make('button','Reset password','secondary');reset.onclick=async()=>{if(!confirm('Verify '+u.username+'’s identity before creating a reset link. Continue?'))return;reset.disabled=true;try{const x=await Account.request('/api/admin/password-reset',{id:u.id});const status=$('user-status');status.replaceChildren(make('p','Share privately with '+u.username+'. Expires in 30 minutes; usable once.'));const link=make('input');link.type='text';link.readOnly=true;link.value=location.origin+'/login.html#reset='+x.token;link.setAttribute('aria-label','Private password reset link');link.onclick=()=>link.select();status.append(link)}catch(e){$('user-status').textContent=e.message}finally{reset.disabled=false}};actions.append(reset)}cell(actions)}else cell(make('span','Protected','protected'));body.append(tr)}
 if(!filtered.length){const tr=make('tr'),td=make('td',users.length?'No matching users.':'No users found.');td.colSpan=5;tr.append(td);body.append(tr)}$('page-summary').textContent=filtered.length?'Showing '+((page-1)*size+1)+'–'+Math.min(page*size,filtered.length)+' of '+filtered.length+' users':'0 users';$('page-number').textContent=page+' / '+pages;$('previous').disabled=page===1;$('next').disabled=page===pages;}
 async function load(){ $('refresh-users').disabled=true;try{users=await Account.request('/api/admin/users');render();return true}catch(e){$('user-status').textContent=e.message;return false}finally{$('refresh-users').disabled=false}}
 for(const id of ['role-filter','status-filter'])$(id).onchange=()=>{page=1;render()};$('user-search').oninput=()=>{page=1;render()};$('previous').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('refresh-users').onclick=async()=>{$('user-status').textContent='';await load()};$('cancel-change').onclick=()=>{if(!busy){pending=null;$('account-confirm').close()}};$('account-confirm').addEventListener('cancel',e=>{if(busy)e.preventDefault();else pending=null});
 $('confirm-change').onclick=async()=>{if(busy||!pending)return;busy=true;$('confirm-change').disabled=$('cancel-change').disabled=true;const {u,role}=pending;try{await Account.request(role?'/api/admin/user-role':'/api/admin/user-status',role?{id:u.id,role,previous_role:u.role}:{id:u.id,disabled:!u.disabled});$('account-confirm').close();pending=null;$('user-status').textContent=role?'Role updated.':u.disabled?'Account enabled.':'Account disabled.';await load()}catch(e){$('confirm-error').textContent=e.message}finally{busy=false;$('confirm-change').disabled=$('cancel-change').disabled=false}};
 await load();
}).catch(()=>{});
